Map<Integer, String> map2 = new TreeMap<>(Map.of(2, "b", 4, "d", 6, "f"));

// Merge by key order
EntryStream<Integer, String> merged = EntryStream.merge(map1, map2,
    (e1, e2) -> e1.getKey() < e2.getKey() ? MergeResult.TAKE_FIRST : MergeResult.TAKE_SECOND
);
