Stream.of("1-3", "5-7")
      .mapMultiToLong((range, consumer) -> {
          String[] parts = range.split("-");
          long start = Long.parseLong(parts[0]);
          long end = Long.parseLong(parts[1]);
          for (long i = start; i <= end; i++) {
              consumer.accept(i);
          }
      })
      .toArray();   // returns [1, 2, 3, 5, 6, 7]

